975	func proxyTransferParamsSig(req ProxyTransferRequest) string {
976		b, _ := json.Marshal(struct {
977			Kind   string `json:"kind"`
978			AuthID string `json:"auth_id"`
979			Reason string `json:"reason"`
980		}{"proxy_transfer", req.AuthID, req.Reason})
981		return string(b)
982	}
983	
984	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
985	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
986	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
987	// 操作者记为实际受托账户并可通过授权编号追溯。
988	//
989	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
990	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
991	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
992	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
993	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
994	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
995	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
996		missing := []string{}
997		if strings.TrimSpace(req.Operator) == "" {
998			missing = append(missing, "operator")
999		}
1000		if strings.TrimSpace(req.Reason) == "" {
1001			missing = append(missing, "reason")
1002		}
1003		if strings.TrimSpace(req.RequestID) == "" {
1004			missing = append(missing, "request_id")
1005		}
1006		if strings.TrimSpace(req.AuthID) == "" {
1007			missing = append(missing, "auth_id")
1008		}
1009		if len(missing) > 0 {
1010			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1011				ErrInvalidArgument, strings.Join(missing, ", "))
1012		}
1013		r.mu.Lock()
1014		defer r.mu.Unlock()
1015		if err := r.checkOpen(); err != nil {
1016			return ProxyTransferResult{}, err
1017		}
1018	
1019		now := r.now()
1020		key := requestKey(req.Operator, req.RequestID)
1021		sig := proxyTransferParamsSig(req)
1022		if prev, ok := r.state.Requests[key]; ok {
1023			return r.replayProxyTransfer(prev, sig)
1024		}
1025	
1026		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1027			if !isValidationErr(bizErr) {
1028				r.state.Requests[key] = request{
1029					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1030					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1031				}
1032				_ = r.commit()
1033			}
1034			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1035		}
1036	
1037		a := r.state.Authzs[req.AuthID]
1038		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1039		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1040		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1041		// 追溯。
1042		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1043		a.Status = "used"
1044		a.UsedTxSeq = out.seq
1045		a.UsedAt = now
1046		r.state.Authzs[a.ID] = a
1047		authSeq := r.state.NextAuthSeq + 1
1048		r.state.NextAuthSeq = authSeq
1049		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1050			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1051			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1052			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1053		})
1054		r.state.Requests[key] = request{
1055			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1056			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1057			Version: out.toVer(), TxSeq: out.seq,
1058		}
1059		if err := r.commit(); err != nil {
1060			return ProxyTransferResult{}, err
1061		}
1062		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1063			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1064			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1065			Remainder: out.royalty.Remainder}, nil
1066	}
1067	
1068	func (r *Registry) checkProxyTransfer(req ProxyTransferRequest, now time.Time) error {
1069		a, ok := r.state.Authzs[req.AuthID]
1070		if !ok {
1071			return fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
1072		}
1073		op, ok := r.state.Accounts[req.Operator]
1074		if !ok {
1075			return fmt.Errorf("%w: 受托人账户 %s", ErrNotFound, req.Operator)
1076		}
1077		granter, gOk := r.state.Accounts[a.GranterID]
1078		to, tOk := r.state.Accounts[a.ToID]
1079		if req.Operator != a.TrusteeID {
1080			return fmt.Errorf("%w: 账户 %s 不是授权 %s 的受托人",
1081				ErrForbidden, req.Operator, req.AuthID)
1082		}
1083		if !gOk {
1084			return fmt.Errorf("%w: 授权人账户 %s", ErrNotFound, a.GranterID)
1085		}
1086		if !tOk {
1087			return fmt.Errorf("%w: 接收账户 %s", ErrNotFound, a.ToID)
1088		}
1089		if !op.Active {
1090			return fmt.Errorf("%w: 受托人账户 %s", ErrAccountInactive, req.Operator)
1091		}
1092		if !granter.Active {
1093			return fmt.Errorf("%w: 授权人账户 %s", ErrAccountInactive, a.GranterID)
1094		}
1095		if !to.Active {
1096			return fmt.Errorf("%w: 接收账户 %s", ErrAccountInactive, a.ToID)
1097		}
1098		switch authzCurrentStatus(a, now) {
1099		case AuthRevoked:
1100			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationRevoked, req.AuthID)
1101		case AuthExpired:
1102			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationExpired, req.AuthID)
1103		case AuthUsed:
1104			return fmt.Errorf("%w: 授权 %s", ErrAuthorizationUsed, req.AuthID)
1105		}
1106		// 授权只在创建时绑定的持有版本上有效；版本单调递增，藏品即使回到
1107		// 授权人手中也不会回到旧版本，旧授权据此永久失效。
1108		h, ok := r.state.Holdings[a.ItemID]
1109		if !ok {
1110			return fmt.Errorf("%w: 藏品 %s 没有持有记录", ErrNotFound, a.ItemID)
1111		}
1112		if h.OwnerID != a.GranterID || h.Version != a.GrantVer {
1113			return fmt.Errorf("%w: 藏品 %s 当前为 %s 版本 %d，授权绑定 %s 版本 %d",
1114				ErrConflict, a.ItemID, h.OwnerID, h.Version, a.GranterID, a.GrantVer)
1115		}
1116		return nil
1117	}
1118	
1119	func (r *Registry) replayProxyTransfer(prev request, sig string) (ProxyTransferResult, error) {
1120		if prev.Kind != "proxy_transfer" || prev.Params != sig {
1121			return ProxyTransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1122				ErrRequestConflict, prev.Operator, prev.RequestID)
1123		}
1124		res := ProxyTransferResult{AuthID: prev.AuthID, ItemID: prev.ItemID, FromID: prev.FromID,
1125			ToID: prev.ToID, Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
1126		if prev.Rejected {
1127			res.Err = codeErr(prev.Reason)
1128			return res, res.Err
1129		}
1130		// 回放首次成功的金额：授权到期、账户停用或藏品再次易手后仍返回
1131		// 原价款与应付明细，不重复计入。
1132		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
1133		return res, nil
1134	}
