1265	// ---- 幂等辅助 ----
1266	
1267	// requestKey 由完整的操作者账户编号与完整的请求号共同确定一条请求记录。
1268	// 采用 JSON 数组编码而非直接拼接：账户编号或请求号本身允许包含零字符
1269	// （U+0000）等任意字符，直接拼接会让 ("a", "b\x00c") 与 ("a\x00b", "c")
1270	// 之类不同的组合得到相同的键，导致不同账户互相占用请求号、回放别人的
1271	// 结果。JSON 编码对任意字符都无歧义，两个组成部分各自完整参与键的构成。
1272	func requestKey(operator, requestID string) string {
1273		b, _ := json.Marshal([2]string{operator, requestID})
1274		return string(b)
1275	}
1276	
1277	// isValidationErr 判定是否为请求本身不成立的错误：必填缺失，或引用了
1278	// 不存在的账户、系列、藏品。这类请求不占用请求号、不落任何记录，引用
1279	// 对象后来补建后仍可用原请求号完整执行一次；其余拒绝（封存、停用、
1280	// 版本冲突、无权、编号已用、收发同人等状态类业务拒绝）按首次结果记忆
1281	// 并回放。
1282	func isValidationErr(err error) bool {
1283		return errors.Is(err, ErrInvalidArgument) || errors.Is(err, ErrNotFound)
1284	}
1285	
1286	var errCodes = map[error]string{
1287		ErrNotFound:             "not_found",
1288		ErrAlreadyExists:        "already_exists",
1289		ErrAccountInactive:      "account_inactive",
1290		ErrSeriesSealed:         "series_sealed",
1291		ErrConflict:             "conflict",
1292		ErrSameAccount:          "same_account",
1293		ErrForbidden:            "forbidden",
1294		ErrAuthorizationRevoked: "authorization_revoked",
1295		ErrAuthorizationExpired: "authorization_expired",
1296		ErrAuthorizationUsed:    "authorization_used",
1297		ErrRoyaltyFrozen:        "royalty_frozen",
1298		ErrSplitIntentRejected:  "split_intent_rejected",
1299		ErrSplitIntentWithdrawn: "split_intent_withdrawn",
1300		ErrSplitIntentInvalid:   "split_intent_invalid",
1301		ErrSplitIntentExpired:   "split_intent_expired",
1302		ErrSplitAnswered:        "split_answered",
1303	}
1304	
1305	var codeErrs = map[string]error{
1306		"not_found":              ErrNotFound,
1307		"already_exists":         ErrAlreadyExists,
1308		"account_inactive":       ErrAccountInactive,
1309		"series_sealed":          ErrSeriesSealed,
1310		"conflict":               ErrConflict,
1311		"same_account":           ErrSameAccount,
1312		"forbidden":              ErrForbidden,
1313		"authorization_revoked":  ErrAuthorizationRevoked,
1314		"authorization_expired":  ErrAuthorizationExpired,
1315		"authorization_used":     ErrAuthorizationUsed,
1316		"royalty_frozen":         ErrRoyaltyFrozen,
1317		"split_intent_rejected":  ErrSplitIntentRejected,
1318		"split_intent_withdrawn": ErrSplitIntentWithdrawn,
1319		"split_intent_invalid":   ErrSplitIntentInvalid,
1320		"split_intent_expired":   ErrSplitIntentExpired,
1321		"split_answered":         ErrSplitAnswered,
1322	}
1323	
1324	func errCode(err error) string {
1325		for sentinel, code := range errCodes {
1326			if errors.Is(err, sentinel) {
1327				return code
1328			}
1329		}
1330		return "rejected"
1331	}
1332	
1333	func codeErr(code string) error {
1334		if e, ok := codeErrs[code]; ok {
1335			return e
1336		}
1337		return errors.New("registry: 请求曾被拒绝")
1338	}
