97	// TestRevokeAuthzForbiddenSaveFailure 覆盖：非授权人撤销的 ErrForbidden
98	// 拒绝在拒绝结果自身落盘失败时，返回实际保存错误与空结果，业务错误被掩盖的
99	// 问题得到修正；请求号不被占用，授权内容、授权变更记录与藏品持有保持操作前
100	// 状态。保存恢复且拒绝条件仍在时，原请求重提先成功保存此次拒绝再返回
101	// ErrForbidden（首次重提不标回放、结果带原授权编号与业务错误），此后完全
102	// 相同的提交才回放该拒绝；授权人仍可正常撤销该授权。
103	func TestRevokeAuthzForbiddenSaveFailure(t *testing.T) {
104		r := mustCreate(t, tempDir(t))
105		authzWorld(t, r)
106		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
107			t.Fatal(err)
108		}
109		req := revokeAuthzSaveReq("bob", "a1", "rv-bob")
110	
111		blockBatchSave(t, r)
112		res, err := r.RevokeAuthorization(req)
113		assertRevokeAuthzSaveFailureEmpty(t, res, err)
114		assertRevokeRequestFree(t, r, req)
115		// 授权内容与授权变更记录保持操作前状态：仍有效，只有创建记录一条。
116		a, err := r.GetAuthorization("a1")
117		if err != nil || a.Status != AuthActive || a.RevokedAt != (time.Time{}) {
118			t.Fatalf("未保存的无权拒绝不应改变授权: %+v, %v", a, err)
119		}
120		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 || evs[0].Kind != "create" {
121			t.Fatalf("未保存的无权拒绝不应新增授权变更记录: %+v", evs)
122		}
123		assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)
124	
125		// 保存条件未恢复时再次提交同一请求：仍重新尝试保存并失败，不能把上次
126		// 未保存的拒绝当成已保存拒绝回放。
127		res, err = r.RevokeAuthorization(req)
128		assertRevokeAuthzSaveFailureEmpty(t, res, err)
129		assertRevokeRequestFree(t, r, req)
130	
131		// 保存条件恢复后，其他操作成功保存也不能把这次未保存的拒绝带入登记册。
132		restoreBatchSave(t, r)
133		if err := r.RegisterAccount("dave", "路人"); err != nil {
134			t.Fatal(err)
135		}
136		assertRevokeRequestFree(t, r, req)
137		a, _ = r.GetAuthorization("a1")
138		if a.Status != AuthActive {
139			t.Fatalf("其他操作保存后授权仍应有效: %+v", a)
140		}
141	
142		// 原请求重提：拒绝条件仍在，先成功保存此次拒绝，再返回业务错误本身；
143		// 结果带原授权编号与业务错误，这次重新处理不标记为回放。
144		res, err = r.RevokeAuthorization(req)
145		if !errors.Is(err, ErrForbidden) {
146			t.Fatalf("重提应在保存成功后返回 ErrForbidden: %v", err)
147		}
148		if res.Replayed || res.AuthID != "a1" || !errors.Is(res.Err, ErrForbidden) ||
149			res.Status != "" {
150			t.Fatalf("无权拒绝的重提结果异常: %+v", res)
151		}
152		assertRevokeRequestSaved(t, r, req)
153		a, _ = r.GetAuthorization("a1")
154		if a.Status != AuthActive {
155			t.Fatalf("无权拒绝不应改变授权状态: %+v", a)
156		}
157		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 {
158			t.Fatalf("无权拒绝不应新增授权变更记录: %+v", evs)
159		}
160	
161		// 拒绝已保存：相同内容重提回放原拒绝。
162		res, err = r.RevokeAuthorization(req)
163		if !errors.Is(err, ErrForbidden) || !res.Replayed || res.AuthID != "a1" ||
164			!errors.Is(res.Err, ErrForbidden) {
165			t.Fatalf("保存后的重提应回放原拒绝: %+v, err %v", res, err)
166		}
167	
168		// 授权人仍可正常撤销该授权（业务含义不变），撤销成功后新增一条记录。
169		ok, err := r.RevokeAuthorization(revokeAuthzSaveReq("alice", "a1", "rv-ok"))
170		if err != nil || ok.Status != AuthRevoked || ok.Replayed {
171			t.Fatalf("授权人应仍可正常撤销: %+v, %v", ok, err)
172		}
173		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 2 ||
174			evs[1].Kind != "revoke" || evs[1].ToStatus != AuthRevoked {
175			t.Fatalf("正常撤销应新增一条撤销记录: %+v", evs)
176		}
177	}
