339	// TestRevokeAuthzFailedSaveRequestIDReusable 覆盖：保存失败的拒绝不占用请求
340	// 号——该操作者用同一请求号撤销另一份自己有权撤销的授权时不能遭遇请求号
341	// 冲突；只有实际保存过的结果才继续适用原有的同号不同参数冲突规则。
342	func TestRevokeAuthzFailedSaveRequestIDReusable(t *testing.T) {
343		r := mustCreate(t, tempDir(t))
344		setupUsedAuthzWorld(t, r)
345		// alice 撤销已使用的 a2 将被拒绝；a1 未使用，alice 有权撤销。
346		failedReq := revokeAuthzSaveReq("alice", "a2", "rv-x")
347		otherReq := revokeAuthzSaveReq("alice", "a1", "rv-x")
348	
349		blockBatchSave(t, r)
350		res, err := r.RevokeAuthorization(failedReq)
351		assertRevokeAuthzSaveFailureEmpty(t, res, err)
352		assertRevokeRequestFree(t, r, failedReq)
353	
354		// 保存条件未恢复时重放原失败请求：仍只失败在保存上。
355		res, err = r.RevokeAuthorization(failedReq)
356		assertRevokeAuthzSaveFailureEmpty(t, res, err)
357		assertRevokeRequestFree(t, r, failedReq)
358	
359		// 保存恢复后，同一操作者用同一请求号撤销另一份自己有权撤销的授权：
360		// 未保存的拒绝不适用冲突规则，请求正常成功且不标回放。
361		restoreBatchSave(t, r)
362		res, err = r.RevokeAuthorization(otherReq)
363		if err != nil {
364			t.Fatalf("未保存的拒绝不应阻碍同号撤销另一份有权撤销的授权: %v", err)
365		}
366		if res.Replayed || res.Err != nil || res.AuthID != "a1" || res.Status != AuthRevoked {
367			t.Fatalf("同号撤销另一份授权的结果异常: %+v", res)
368		}
369		a1, _ := r.GetAuthorization("a1")
370		if a1.Status != AuthRevoked {
371			t.Fatalf("a1 应已撤销: %+v", a1)
372		}
373		// 已使用的 a2 不受影响。
374		a2, _ := r.GetAuthorization("a2")
375		if a2.Status != AuthUsed {
376			t.Fatalf("a2 应仍为已使用: %+v", a2)
377		}
378	
379		// 请求号此刻已被实际保存的 a1 成功结果占用：同号不同参数（改撤 a2）
380		// 按原有规则返回 ErrRequestConflict。
381		if _, err := r.RevokeAuthorization(failedReq); !errors.Is(err, ErrRequestConflict) {
382			t.Fatalf("实际保存过的结果才应触发同号不同参数冲突: %v", err)
383		}
384		// 完全相同的已保存请求（撤 a1）回放首次成功结果。
385		res, err = r.RevokeAuthorization(otherReq)
386		if err != nil || !res.Replayed || res.AuthID != "a1" || res.Status != AuthRevoked {
387			t.Fatalf("已保存的同号成功结果应被回放: %+v, err %v", res, err)
388		}
389	}
390	
391	// TestRevokeAuthzRejectSaveFailureAfterReopen 覆盖磁盘视角：原数据可读时
392	// 拒绝结果保存失败后关闭重开，看到的仍是拒绝前状态——授权未改变、请求号
393	// 未占用；恢复保存后用原请求重提才首次保存该拒绝，再次提交回放。
394	func TestRevokeAuthzRejectSaveFailureAfterReopen(t *testing.T) {
395		dir := tempDir(t)
396		r := mustCreate(t, dir)
397		authzWorld(t, r)
398		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
399			t.Fatal(err)
400		}
401		req := revokeAuthzSaveReq("bob", "a1", "rv-bob")
402	
403		blockBatchSave(t, r)
404		res, err := r.RevokeAuthorization(req)
405		assertRevokeAuthzSaveFailureEmpty(t, res, err)
406	
407		if err := r.Close(); err != nil {
408			t.Fatal(err)
409		}
410		r2, err := Open(dir)
411		if err != nil {
412			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
413		}
414		t.Cleanup(func() { _ = r2.Close() })
415		if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
416			t.Fatal("重开后未保存的拒绝不应占用请求号")
417		}
418		if a, _ := r2.GetAuthorization("a1"); a.Status != AuthActive {
419			t.Fatalf("重开后授权应仍有效: %+v", a)
420		}
421		if evs, _ := r2.AuthorizationHistory("i1"); len(evs) != 1 {
422			t.Fatalf("重开后授权变更记录应只有创建: %+v", evs)
423		}
424	
425		restoreBatchSave(t, r2)
426		res2, err := r2.RevokeAuthorization(req)
427		if !errors.Is(err, ErrForbidden) || res2.Replayed ||
428			!errors.Is(res2.Err, ErrForbidden) || res2.AuthID != "a1" {
429			t.Fatalf("重开后重提应首次保存无权拒绝: %+v, err %v", res2, err)
430		}
431		res2, err = r2.RevokeAuthorization(req)
432		if !errors.Is(err, ErrForbidden) || !res2.Replayed {
433			t.Fatalf("再次提交应回放已保存的无权拒绝: %+v, err %v", res2, err)
434		}
435	}
436	
437	// TestRevokeAuthzValidationIgnoresSaveFailure 覆盖：必填内容缺失与授权不
438	// 存在的请求直接按原错误拒绝、不占用请求号、不要求保存，即使数据位置暂时
439	// 不可写也仍返回原参数/引用错误，不能改报保存错误。
440	func TestRevokeAuthzValidationIgnoresSaveFailure(t *testing.T) {
441		r := mustCreate(t, tempDir(t))
442		authzWorld(t, r)
443		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
444			t.Fatal(err)
445		}
446	
447		blockBatchSave(t, r)
448		defer restoreBatchSave(t, r)
449	
450		// 必填内容缺失：返回 ErrInvalidArgument，不是保存错误。
451		if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{}); !errors.Is(err, ErrInvalidArgument) {
452			t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
453		}
454		missing := revokeAuthzSaveReq("alice", "a1", "rv-miss")
455		missing.AuthID = ""
456		if _, err := r.RevokeAuthorization(missing); !errors.Is(err, ErrInvalidArgument) {
457			t.Fatalf("必填缺失应返回 ErrInvalidArgument: %v", err)
458		}
459	
460		// 授权不存在：返回 ErrNotFound（结果带授权编号与业务错误），不是保存
461		// 错误，也不占用请求号。
462		notFoundReq := revokeAuthzSaveReq("alice", "ghost", "rv-nf")
463		res, err := r.RevokeAuthorization(notFoundReq)
464		if !errors.Is(err, ErrNotFound) {
465			t.Fatalf("授权不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
466		}
467		if res.AuthID != "ghost" || !errors.Is(res.Err, ErrNotFound) || res.Replayed {
468			t.Fatalf("授权不存在的结果异常: %+v", res)
469		}
470		assertRevokeRequestFree(t, r, notFoundReq)
471	
472		// 保存条件恢复后，同一操作者用同一请求号撤销真实存在的授权应正常成功：
473		// 引用不存在没有占用请求号。
474		restoreBatchSave(t, r)
475		res, err = r.RevokeAuthorization(revokeAuthzSaveReq("alice", "a1", "rv-nf"))
476		if err != nil || res.Replayed || res.AuthID != "a1" || res.Status != AuthRevoked {
477			t.Fatalf("引用不存在不应占用请求号，同号撤销真实授权应成功: %+v, err %v", res, err)
478		}
479	}
