package registry

import (
	"errors"
	"os"
	"testing"
	"time"
)

// 本文件为撤销代转授权补充"拒绝结果保存失败"场景的回归保障，与创建授权
// （authorization_save_failure_test.go）及发行、转让、拆分意向的同类用例
// 行为对齐：非授权人请求撤销得到的 ErrForbidden、授权人撤销已使用授权得到
// 的 ErrAuthorizationUsed 都属于需要落盘记忆的状态类业务拒绝，登记册应保存
// 这两种拒绝，让同一请求重提时返回首次结果。若本次拒绝结果尚未写入原登记册
// 就发生写入失败，RevokeAuthorization 必须返回实际保存错误，不能只返回上述
// 业务错误，让调用者误以为拒绝结果已经记住。
//
// 保存失败时返回的结果必须为空：不带授权编号与状态，Replayed 为 false，
// 结果内的 Err 为空，单独返回的 error 保留保存失败的原因。授权内容、授权
// 变更记录及藏品当前持有人和版本保持操作前的状态；该操作者的本次请求号没有
// 被占用——即使写入失败后原登记册数据暂时无法读取，也不能让尚未保存的拒绝
// 留在当前已打开的登记册中，或随之后另一次正常操作被保存下来。保存条件恢复
// 后用同一操作者、请求号、授权编号和原因重新提交，按当时的授权情况重新
// 处理：拒绝条件仍存在时先成功保存此次拒绝再返回相应业务错误（首次重提不标
// 回放），此后完全相同的提交才回放它。失败保存的请求也不能使该操作者使用
// 同号撤销另一份自己有权撤销的授权时遭遇请求号冲突；只有实际保存过的结果
// 才继续适用原有的同号不同参数冲突规则。
//
// 必填内容缺失及授权不存在仍直接按原错误拒绝、不占用请求号，也不因当前无法
// 保存而变成保存错误。
//
// 失败注入方式与其他场景共用：在临时文件路径 .registry.json.tmp 上预先
// 建一个目录，save 在 OpenFile 阶段即以 EISDIR 失败，原快照完好可读；
// 另有用例同时破坏数据文件，覆盖"原数据暂时无法读取"的情形。

// revokeAuthzSaveReq 构造一条撤销授权请求。
func revokeAuthzSaveReq(op, authID, rid string) RevokeAuthorizationRequest {
	return RevokeAuthorizationRequest{Operator: op, Reason: "撤销授权", RequestID: rid, AuthID: authID}
}

// setupUsedAuthzWorld 建立两份授权：a1 仍有效、未使用；a2 已由受托人 bob
// 代转给 carol（已使用）。代转后藏品 i1 在 carol 手中、版本 2；授权变更
// 记录依次为 create a1（序号 1）、create a2（序号 2）、use a2（序号 3）。
// a1 虽因藏品易手无法再用于代转，但尚未使用，授权人 alice 仍可撤销。
func setupUsedAuthzWorld(t *testing.T, r *Registry) {
	t.Helper()
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.CreateAuthorization(createAuthReq(r, "a2", time.Hour)); err != nil {
		t.Fatal(err)
	}
	if _, err := r.ProxyTransfer(proxyReq("bob", "a2", "p-a2")); err != nil {
		t.Fatal(err)
	}
}

// assertRevokeAuthzSaveFailureEmpty 核对撤销"拒绝结果保存失败"的返回：
// error 是保存错误而非任何业务拒绝（含授权类的已使用、已撤销、已过期
// 哨兵）；结果为空——不携带授权编号或状态，业务错误为空，也不标记为重复
// 返回。
func assertRevokeAuthzSaveFailureEmpty(t *testing.T, res RevokeAuthorizationResult, err error) {
	t.Helper()
	assertSaveFailureError(t, err)
	for _, s := range []error{ErrAuthorizationUsed, ErrAuthorizationRevoked, ErrAuthorizationExpired} {
		if errors.Is(err, s) {
			t.Fatalf("返回的应是保存错误，不能是业务拒绝 %v: %v", s, err)
		}
	}
	if res.AuthID != "" || res.Status != "" || res.Replayed || res.Err != nil {
		t.Fatalf("拒绝结果保存失败必须返回空结果: %+v", res)
	}
}

// assertRevokeRequestFree 核对请求号未被这次未保存的拒绝占用（在同一个已
// 打开的登记册上检查）。
func assertRevokeRequestFree(t *testing.T, r *Registry, req RevokeAuthorizationRequest) {
	t.Helper()
	if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
		t.Fatalf("未保存的拒绝不应占用请求号 %s", req.RequestID)
	}
}

// assertRevokeRequestSaved 核对拒绝结果已登记落盘。
func assertRevokeRequestSaved(t *testing.T, r *Registry, req RevokeAuthorizationRequest) {
	t.Helper()
	prev, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]
	if !ok {
		t.Fatalf("拒绝保存成功后应登记请求结果，请求号 %s 却空闲", req.RequestID)
	}
	if !prev.Rejected || prev.AuthID != req.AuthID {
		t.Fatalf("登记的请求结果异常: %+v", prev)
	}
}

// TestRevokeAuthzForbiddenSaveFailure 覆盖：非授权人撤销的 ErrForbidden
// 拒绝在拒绝结果自身落盘失败时，返回实际保存错误与空结果，业务错误被掩盖的
// 问题得到修正；请求号不被占用，授权内容、授权变更记录与藏品持有保持操作前
// 状态。保存恢复且拒绝条件仍在时，原请求重提先成功保存此次拒绝再返回
// ErrForbidden（首次重提不标回放、结果带原授权编号与业务错误），此后完全
// 相同的提交才回放该拒绝；授权人仍可正常撤销该授权。
func TestRevokeAuthzForbiddenSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	req := revokeAuthzSaveReq("bob", "a1", "rv-bob")

	blockBatchSave(t, r)
	res, err := r.RevokeAuthorization(req)
	assertRevokeAuthzSaveFailureEmpty(t, res, err)
	assertRevokeRequestFree(t, r, req)
	// 授权内容与授权变更记录保持操作前状态：仍有效，只有创建记录一条。
	a, err := r.GetAuthorization("a1")
	if err != nil || a.Status != AuthActive || a.RevokedAt != (time.Time{}) {
		t.Fatalf("未保存的无权拒绝不应改变授权: %+v, %v", a, err)
	}
	if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 || evs[0].Kind != "create" {
		t.Fatalf("未保存的无权拒绝不应新增授权变更记录: %+v", evs)
	}
	assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)

	// 保存条件未恢复时再次提交同一请求：仍重新尝试保存并失败，不能把上次
	// 未保存的拒绝当成已保存拒绝回放。
	res, err = r.RevokeAuthorization(req)
	assertRevokeAuthzSaveFailureEmpty(t, res, err)
	assertRevokeRequestFree(t, r, req)

	// 保存条件恢复后，其他操作成功保存也不能把这次未保存的拒绝带入登记册。
	restoreBatchSave(t, r)
	if err := r.RegisterAccount("dave", "路人"); err != nil {
		t.Fatal(err)
	}
	assertRevokeRequestFree(t, r, req)
	a, _ = r.GetAuthorization("a1")
	if a.Status != AuthActive {
		t.Fatalf("其他操作保存后授权仍应有效: %+v", a)
	}

	// 原请求重提：拒绝条件仍在，先成功保存此次拒绝，再返回业务错误本身；
	// 结果带原授权编号与业务错误，这次重新处理不标记为回放。
	res, err = r.RevokeAuthorization(req)
	if !errors.Is(err, ErrForbidden) {
		t.Fatalf("重提应在保存成功后返回 ErrForbidden: %v", err)
	}
	if res.Replayed || res.AuthID != "a1" || !errors.Is(res.Err, ErrForbidden) ||
		res.Status != "" {
		t.Fatalf("无权拒绝的重提结果异常: %+v", res)
	}
	assertRevokeRequestSaved(t, r, req)
	a, _ = r.GetAuthorization("a1")
	if a.Status != AuthActive {
		t.Fatalf("无权拒绝不应改变授权状态: %+v", a)
	}
	if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 {
		t.Fatalf("无权拒绝不应新增授权变更记录: %+v", evs)
	}

	// 拒绝已保存：相同内容重提回放原拒绝。
	res, err = r.RevokeAuthorization(req)
	if !errors.Is(err, ErrForbidden) || !res.Replayed || res.AuthID != "a1" ||
		!errors.Is(res.Err, ErrForbidden) {
		t.Fatalf("保存后的重提应回放原拒绝: %+v, err %v", res, err)
	}

	// 授权人仍可正常撤销该授权（业务含义不变），撤销成功后新增一条记录。
	ok, err := r.RevokeAuthorization(revokeAuthzSaveReq("alice", "a1", "rv-ok"))
	if err != nil || ok.Status != AuthRevoked || ok.Replayed {
		t.Fatalf("授权人应仍可正常撤销: %+v, %v", ok, err)
	}
	if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 2 ||
		evs[1].Kind != "revoke" || evs[1].ToStatus != AuthRevoked {
		t.Fatalf("正常撤销应新增一条撤销记录: %+v", evs)
	}
}

// TestRevokeAuthzUsedSaveFailure 覆盖：授权人撤销已使用授权的
// ErrAuthorizationUsed 拒绝在拒绝结果自身落盘失败时，同样返回实际保存错误
// 与空结果；已使用终态、使用关联与授权变更记录保持操作前内容，藏品持有
// 不变。保存恢复后原请求重提重新保存该拒绝（首次不标回放），再次提交才
// 回放。
func TestRevokeAuthzUsedSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupUsedAuthzWorld(t, r)
	req := revokeAuthzSaveReq("alice", "a2", "rv-used")

	blockBatchSave(t, r)
	res, err := r.RevokeAuthorization(req)
	assertRevokeAuthzSaveFailureEmpty(t, res, err)
	assertRevokeRequestFree(t, r, req)
	// 已使用终态及其使用关联保持操作前内容。
	a, err := r.GetAuthorization("a2")
	if err != nil || a.Status != AuthUsed || a.UsedTxSeq != 2 {
		t.Fatalf("未保存的拒绝不应改变已使用授权: %+v, %v", a, err)
	}
	if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 ||
		evs[2].Kind != "use" || evs[2].AuthID != "a2" {
		t.Fatalf("授权变更记录应保持操作前的 3 条: %+v", evs)
	}
	assertHoldingUnchanged(t, r, "i1", "carol", 2, 2)

	// 保存仍被阻断时再次提交：仍失败在保存上，不能回放未保存的拒绝。
	res, err = r.RevokeAuthorization(req)
	assertRevokeAuthzSaveFailureEmpty(t, res, err)
	assertRevokeRequestFree(t, r, req)

	restoreBatchSave(t, r)
	// 重提：先成功保存此次拒绝，再返回 ErrAuthorizationUsed，首次不标回放，
	// 结果带原授权编号与业务错误、状态为空。
	res, err = r.RevokeAuthorization(req)
	if !errors.Is(err, ErrAuthorizationUsed) {
		t.Fatalf("重提应在保存成功后返回 ErrAuthorizationUsed: %v", err)
	}
	if res.Replayed || res.AuthID != "a2" || !errors.Is(res.Err, ErrAuthorizationUsed) ||
		res.Status != "" {
		t.Fatalf("已使用拒绝的重提结果异常: %+v", res)
	}
	assertRevokeRequestSaved(t, r, req)
	a, _ = r.GetAuthorization("a2")
	if a.Status != AuthUsed || a.UsedTxSeq != 2 {
		t.Fatalf("已使用拒绝不应改变授权: %+v", a)
	}
	if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 {
		t.Fatalf("已使用拒绝不应新增授权变更记录: %+v", evs)
	}

	// 拒绝已保存：相同内容重提回放原拒绝。
	res, err = r.RevokeAuthorization(req)
	if !errors.Is(err, ErrAuthorizationUsed) || !res.Replayed ||
		res.AuthID != "a2" || !errors.Is(res.Err, ErrAuthorizationUsed) {
		t.Fatalf("保存后的重提应回放原拒绝: %+v, err %v", res, err)
	}
}

// TestRevokeAuthzRejectSaveFailureUnreadableDisk 覆盖：拒绝结果保存失败且
// 原数据暂时无法读取（commit 无法按磁盘重建状态）时，未保存的拒绝也不能
// 留在当前已打开的登记册中；恢复正常读写后其他操作成功保存不带入这次拒绝，
// 原请求重提才首次保存对应业务拒绝，再次提交才回放。无权与已使用两种拒绝
// 分别覆盖。
func TestRevokeAuthzRejectSaveFailureUnreadableDisk(t *testing.T) {
	t.Run("forbidden", func(t *testing.T) {
		r := mustCreate(t, tempDir(t))
		authzWorld(t, r)
		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
			t.Fatal(err)
		}
		req := revokeAuthzSaveReq("bob", "a1", "rv-bob")

		orig, err := os.ReadFile(dataFile(r.dir))
		if err != nil {
			t.Fatal(err)
		}
		blockBatchSave(t, r)
		if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
			t.Fatal(err)
		}

		res, err := r.RevokeAuthorization(req)
		assertRevokeAuthzSaveFailureEmpty(t, res, err)
		// 状态未能重建时也必须显式撤销：请求号空闲，授权仍有效，历史只有
		// 创建记录。
		assertRevokeRequestFree(t, r, req)
		a, _ := r.GetAuthorization("a1")
		if a.Status != AuthActive {
			t.Fatalf("不可读磁盘失败后授权不应改变: %+v", a)
		}
		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 1 {
			t.Fatalf("不可读磁盘失败后历史应只有创建: %+v", evs)
		}

		if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
			t.Fatal(err)
		}
		restoreBatchSave(t, r)
		if err := r.RegisterAccount("dave", "路人"); err != nil {
			t.Fatal(err)
		}
		assertRevokeRequestFree(t, r, req)

		res, err = r.RevokeAuthorization(req)
		if !errors.Is(err, ErrForbidden) || res.Replayed ||
			!errors.Is(res.Err, ErrForbidden) {
			t.Fatalf("恢复后重提应首次保存无权拒绝: %+v, err %v", res, err)
		}
		res, err = r.RevokeAuthorization(req)
		if !errors.Is(err, ErrForbidden) || !res.Replayed {
			t.Fatalf("再次提交应回放已保存的无权拒绝: %+v, err %v", res, err)
		}
	})

	t.Run("used", func(t *testing.T) {
		r := mustCreate(t, tempDir(t))
		setupUsedAuthzWorld(t, r)
		req := revokeAuthzSaveReq("alice", "a2", "rv-used")

		orig, err := os.ReadFile(dataFile(r.dir))
		if err != nil {
			t.Fatal(err)
		}
		blockBatchSave(t, r)
		if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
			t.Fatal(err)
		}

		res, err := r.RevokeAuthorization(req)
		assertRevokeAuthzSaveFailureEmpty(t, res, err)
		assertRevokeRequestFree(t, r, req)
		a, _ := r.GetAuthorization("a2")
		if a.Status != AuthUsed || a.UsedTxSeq != 2 {
			t.Fatalf("不可读磁盘失败后已使用授权不应改变: %+v", a)
		}
		if evs, _ := r.AuthorizationHistory("i1"); len(evs) != 3 {
			t.Fatalf("不可读磁盘失败后授权变更记录应保持 3 条: %+v", evs)
		}

		if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
			t.Fatal(err)
		}
		restoreBatchSave(t, r)
		if err := r.RegisterAccount("dave", "路人"); err != nil {
			t.Fatal(err)
		}
		assertRevokeRequestFree(t, r, req)

		res, err = r.RevokeAuthorization(req)
		if !errors.Is(err, ErrAuthorizationUsed) || res.Replayed ||
			!errors.Is(res.Err, ErrAuthorizationUsed) {
			t.Fatalf("恢复后重提应首次保存已使用拒绝: %+v, err %v", res, err)
		}
		res, err = r.RevokeAuthorization(req)
		if !errors.Is(err, ErrAuthorizationUsed) || !res.Replayed {
			t.Fatalf("再次提交应回放已保存的已使用拒绝: %+v, err %v", res, err)
		}
	})
}

// TestRevokeAuthzFailedSaveRequestIDReusable 覆盖：保存失败的拒绝不占用请求
// 号——该操作者用同一请求号撤销另一份自己有权撤销的授权时不能遭遇请求号
// 冲突；只有实际保存过的结果才继续适用原有的同号不同参数冲突规则。
func TestRevokeAuthzFailedSaveRequestIDReusable(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupUsedAuthzWorld(t, r)
	// alice 撤销已使用的 a2 将被拒绝；a1 未使用，alice 有权撤销。
	failedReq := revokeAuthzSaveReq("alice", "a2", "rv-x")
	otherReq := revokeAuthzSaveReq("alice", "a1", "rv-x")

	blockBatchSave(t, r)
	res, err := r.RevokeAuthorization(failedReq)
	assertRevokeAuthzSaveFailureEmpty(t, res, err)
	assertRevokeRequestFree(t, r, failedReq)

	// 保存条件未恢复时重放原失败请求：仍只失败在保存上。
	res, err = r.RevokeAuthorization(failedReq)
	assertRevokeAuthzSaveFailureEmpty(t, res, err)
	assertRevokeRequestFree(t, r, failedReq)

	// 保存恢复后，同一操作者用同一请求号撤销另一份自己有权撤销的授权：
	// 未保存的拒绝不适用冲突规则，请求正常成功且不标回放。
	restoreBatchSave(t, r)
	res, err = r.RevokeAuthorization(otherReq)
	if err != nil {
		t.Fatalf("未保存的拒绝不应阻碍同号撤销另一份有权撤销的授权: %v", err)
	}
	if res.Replayed || res.Err != nil || res.AuthID != "a1" || res.Status != AuthRevoked {
		t.Fatalf("同号撤销另一份授权的结果异常: %+v", res)
	}
	a1, _ := r.GetAuthorization("a1")
	if a1.Status != AuthRevoked {
		t.Fatalf("a1 应已撤销: %+v", a1)
	}
	// 已使用的 a2 不受影响。
	a2, _ := r.GetAuthorization("a2")
	if a2.Status != AuthUsed {
		t.Fatalf("a2 应仍为已使用: %+v", a2)
	}

	// 请求号此刻已被实际保存的 a1 成功结果占用：同号不同参数（改撤 a2）
	// 按原有规则返回 ErrRequestConflict。
	if _, err := r.RevokeAuthorization(failedReq); !errors.Is(err, ErrRequestConflict) {
		t.Fatalf("实际保存过的结果才应触发同号不同参数冲突: %v", err)
	}
	// 完全相同的已保存请求（撤 a1）回放首次成功结果。
	res, err = r.RevokeAuthorization(otherReq)
	if err != nil || !res.Replayed || res.AuthID != "a1" || res.Status != AuthRevoked {
		t.Fatalf("已保存的同号成功结果应被回放: %+v, err %v", res, err)
	}
}

// TestRevokeAuthzRejectSaveFailureAfterReopen 覆盖磁盘视角：原数据可读时
// 拒绝结果保存失败后关闭重开，看到的仍是拒绝前状态——授权未改变、请求号
// 未占用；恢复保存后用原请求重提才首次保存该拒绝，再次提交回放。
func TestRevokeAuthzRejectSaveFailureAfterReopen(t *testing.T) {
	dir := tempDir(t)
	r := mustCreate(t, dir)
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	req := revokeAuthzSaveReq("bob", "a1", "rv-bob")

	blockBatchSave(t, r)
	res, err := r.RevokeAuthorization(req)
	assertRevokeAuthzSaveFailureEmpty(t, res, err)

	if err := r.Close(); err != nil {
		t.Fatal(err)
	}
	r2, err := Open(dir)
	if err != nil {
		t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
	}
	t.Cleanup(func() { _ = r2.Close() })
	if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
		t.Fatal("重开后未保存的拒绝不应占用请求号")
	}
	if a, _ := r2.GetAuthorization("a1"); a.Status != AuthActive {
		t.Fatalf("重开后授权应仍有效: %+v", a)
	}
	if evs, _ := r2.AuthorizationHistory("i1"); len(evs) != 1 {
		t.Fatalf("重开后授权变更记录应只有创建: %+v", evs)
	}

	restoreBatchSave(t, r2)
	res2, err := r2.RevokeAuthorization(req)
	if !errors.Is(err, ErrForbidden) || res2.Replayed ||
		!errors.Is(res2.Err, ErrForbidden) || res2.AuthID != "a1" {
		t.Fatalf("重开后重提应首次保存无权拒绝: %+v, err %v", res2, err)
	}
	res2, err = r2.RevokeAuthorization(req)
	if !errors.Is(err, ErrForbidden) || !res2.Replayed {
		t.Fatalf("再次提交应回放已保存的无权拒绝: %+v, err %v", res2, err)
	}
}

// TestRevokeAuthzValidationIgnoresSaveFailure 覆盖：必填内容缺失与授权不
// 存在的请求直接按原错误拒绝、不占用请求号、不要求保存，即使数据位置暂时
// 不可写也仍返回原参数/引用错误，不能改报保存错误。
func TestRevokeAuthzValidationIgnoresSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}

	blockBatchSave(t, r)
	defer restoreBatchSave(t, r)

	// 必填内容缺失：返回 ErrInvalidArgument，不是保存错误。
	if _, err := r.RevokeAuthorization(RevokeAuthorizationRequest{}); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
	}
	missing := revokeAuthzSaveReq("alice", "a1", "rv-miss")
	missing.AuthID = ""
	if _, err := r.RevokeAuthorization(missing); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("必填缺失应返回 ErrInvalidArgument: %v", err)
	}

	// 授权不存在：返回 ErrNotFound（结果带授权编号与业务错误），不是保存
	// 错误，也不占用请求号。
	notFoundReq := revokeAuthzSaveReq("alice", "ghost", "rv-nf")
	res, err := r.RevokeAuthorization(notFoundReq)
	if !errors.Is(err, ErrNotFound) {
		t.Fatalf("授权不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
	}
	if res.AuthID != "ghost" || !errors.Is(res.Err, ErrNotFound) || res.Replayed {
		t.Fatalf("授权不存在的结果异常: %+v", res)
	}
	assertRevokeRequestFree(t, r, notFoundReq)

	// 保存条件恢复后，同一操作者用同一请求号撤销真实存在的授权应正常成功：
	// 引用不存在没有占用请求号。
	restoreBatchSave(t, r)
	res, err = r.RevokeAuthorization(revokeAuthzSaveReq("alice", "a1", "rv-nf"))
	if err != nil || res.Replayed || res.AuthID != "a1" || res.Status != AuthRevoked {
		t.Fatalf("引用不存在不应占用请求号，同号撤销真实授权应成功: %+v, err %v", res, err)
	}
}

package registry

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"syscall"
	"time"
)

// stateVersion 是快照格式的版本标记，未来不兼容变更时可据此识别。
const stateVersion = 1

const (
	dirMode  = 0o755
	fileMode = 0o644
)

// snapshot 是登记册的全量落盘结构。账户、系列、藏品、持有、历史、
// 授权、授权变更记录与请求结果都在同一个快照中，一次操作一次原子
// 替换，保证"藏品已换人就一定有对应历史"。
type snapshot struct {
	Version  int                 `json:"version"`
	Accounts map[string]account  `json:"accounts"`
	Series   map[string]series   `json:"series"`
	Items    map[string]item     `json:"items"`
	Holdings map[string]holding  `json:"holdings"`
	History  []historyEntry      `json:"history"`
	Requests map[string]request  `json:"requests"`
	Authzs   map[string]authzRec `json:"authzs,omitempty"`
	// AuthEvents 是按藏品记录的授权变更（创建/撤销/使用），在藏品
	// 历史之外单独编号，不影响既有历史序号。
	AuthEvents  []authzEvent `json:"auth_events,omitempty"`
	NextSeq     int64        `json:"next_seq"`
	NextAuthSeq int64        `json:"next_auth_seq,omitempty"`
	// Royalties 以转让历史序号为键，记录每笔成功转让的版税计算依据与
	// 应付明细；旧登记册中的转让没有记录，查询时按价款 0 处理，不补造。
	Royalties map[int64]royaltyRec `json:"royalties,omitempty"`
	// RoyaltyEvents 是版税规则变更记录，单独编号。
	RoyaltyEvents  []royaltyEvent `json:"royalty_events,omitempty"`
	NextRoyaltySeq int64          `json:"next_royalty_seq,omitempty"`
	// Intents 是拆分意向表；只记录未来拆分的约定，不影响持有与版税。
	Intents map[string]intentRec `json:"intents,omitempty"`
	// IntentEvents 是拆分意向变更记录（创建/首次答复/撤回），单独编号。
	IntentEvents  []intentEvent `json:"intent_events,omitempty"`
	NextIntentSeq int64         `json:"next_intent_seq,omitempty"`
}

type account struct {
	ID       string `json:"id"`
	Metadata string `json:"metadata"`
	Active   bool   `json:"active"`
}

type series struct {
	ID        string `json:"id"`
	CreatorID string `json:"creator_id"`
	Metadata  string `json:"metadata"`
	Sealed    bool   `json:"sealed"`
	// Royalty 是当前版税规则（按收款账户排序）；空表示不收版税。
	// 首次成功发行或封存后固定，不能再设置。
	Royalty []royaltyShare `json:"royalty,omitempty"`
}

// royaltyShare 是版税规则中一个收款账户的份额。
type royaltyShare struct {
	AccountID string `json:"account_id"`
	Rate      int64  `json:"rate"`
}

// royaltyRec 是一笔成功转让的版税应付记录，与持有变化、历史、请求结果
// 在同一临界区内一次落盘。
type royaltyRec struct {
	TxSeq     int64         `json:"tx_seq"`
	ItemID    string        `json:"item_id"`
	SeriesID  string        `json:"series_id"`
	Price     int64         `json:"price"`
	Payees    []payableLine `json:"payees,omitempty"`
	Remainder int64         `json:"remainder"`
	// OwnerID 是转让前持有人，即剩余收入的归属账户（代转时是授权人，
	// 不是受托人）。
	OwnerID string `json:"owner_id"`
}

// payableLine 是一笔转让中某个收款账户的应付明细，零金额也保留。
type payableLine struct {
	AccountID string `json:"account_id"`
	Rate      int64  `json:"rate"`
	Amount    int64  `json:"amount"`
}

// royaltyEvent 是版税规则变更记录：每次成功设置或清空各一条。
type royaltyEvent struct {
	Seq        int64          `json:"seq"`
	SeriesID   string         `json:"series_id"`
	Operator   string         `json:"operator"`
	Reason     string         `json:"reason"`
	RequestID  string         `json:"request_id"`
	Before     []royaltyShare `json:"before,omitempty"`
	After      []royaltyShare `json:"after,omitempty"`
	OccurredAt time.Time      `json:"occurred_at"`
}

type item struct {
	ID         string `json:"id"`
	SeriesID   string `json:"series_id"`
	BatchNo    string `json:"batch_no"`
	Metadata   string `json:"metadata"`
	IssuedTxID int64  `json:"issued_tx_id"`
}

type holding struct {
	ItemID  string `json:"item_id"`
	OwnerID string `json:"owner_id"`
	Version int64  `json:"version"`
}

type historyEntry struct {
	Seq         int64  `json:"seq"`
	Kind        string `json:"kind"`
	ItemID      string `json:"item_id"`
	Operator    string `json:"operator"`
	Reason      string `json:"reason"`
	RequestID   string `json:"request_id"`
	FromID      string `json:"from_id"`
	ToID        string `json:"to_id"`
	FromVersion int64  `json:"from_version"`
	ToVersion   int64  `json:"to_version"`
	// AuthID 非空表示该转让是受托人凭授权完成的代转。
	AuthID string `json:"auth_id,omitempty"`
}

// authzRec 是一份限时一次性代转授权的落盘状态。授权在创建时绑定藏品
// 当时的持有版本（GrantVer）；持有关系后续无论怎样变化，授权都不会
// 恢复或改变。
type authzRec struct {
	ID        string    `json:"id"`
	ItemID    string    `json:"item_id"`
	GranterID string    `json:"granter_id"`
	TrusteeID string    `json:"trustee_id"`
	ToID      string    `json:"to_id"`
	ExpiresAt time.Time `json:"expires_at"`
	GrantVer  int64     `json:"grant_ver"`
	// Price 是创建授权时确定的代转成交价款（分）；旧数据中的授权没有
	// 该字段，按 0 处理。
	Price int64 `json:"price,omitempty"`
	// Status 只记录非时间派生的终态："revoked" 或 "used"；为空表示
	// 尚未终结，当前是否有效由到期时间实时判断。
	Status    string    `json:"status,omitempty"`
	UsedTxSeq int64     `json:"used_tx_seq,omitempty"`
	UsedAt    time.Time `json:"used_at,omitempty"`
	CreatedAt time.Time `json:"created_at"`
	RevokedAt time.Time `json:"revoked_at,omitempty"`
}

// authzEvent 是授权变更记录：创建、撤销、使用各一条。
type authzEvent struct {
	Seq        int64     `json:"seq"`
	AuthID     string    `json:"auth_id"`
	ItemID     string    `json:"item_id"`
	Kind       string    `json:"kind"` // "create" / "revoke" / "use"
	Operator   string    `json:"operator"`
	Reason     string    `json:"reason"`
	RequestID  string    `json:"request_id"`
	FromStatus string    `json:"from_status,omitempty"`
	ToStatus   string    `json:"to_status"`
	TxSeq      int64     `json:"tx_seq,omitempty"`
	OccurredAt time.Time `json:"occurred_at"`
}

// intentRec 是一份藏品拆分意向的落盘状态。意向在创建时绑定藏品当时的
// 持有版本（GrantVer）；持有版本变化或发起人、任一参与账户停用后意向
// 失效，且不因藏品转回原持有人而恢复。
type intentRec struct {
	ID          string        `json:"id"`
	ItemID      string        `json:"item_id"`
	InitiatorID string        `json:"initiator_id"`
	Shares      []intentShare `json:"shares"` // 按账户排序的分配方案
	GrantVer    int64         `json:"grant_ver"`
	ExpiresAt   time.Time     `json:"expires_at"`
	// Status 只记录非时间派生的终态："rejected" 或 "withdrawn"；为空表示
	// 尚未终结，当前是否有效由持有版本、账户状态与到期时间实时判断。
	Status    string    `json:"status,omitempty"`
	CreatedAt time.Time `json:"created_at"`
	EndedAt   time.Time `json:"ended_at,omitempty"`
}

// intentShare 是拆分意向中一个参与账户的份额与答复。
type intentShare struct {
	AccountID string `json:"account_id"`
	Share     int64  `json:"share"`
	// Answer 是该账户的答复："agree" / "reject"；空表示尚未答复。
	// 发起人列入方案时创建即为 "agree"。
	Answer string `json:"answer,omitempty"`
}

// intentEvent 是拆分意向变更记录：创建、首次答复、撤回各一条；重复答复
// 与重复撤回不新增记录。
type intentEvent struct {
	Seq        int64     `json:"seq"`
	IntentID   string    `json:"intent_id"`
	ItemID     string    `json:"item_id"`
	Kind       string    `json:"kind"` // "create" / "answer" / "withdraw"
	Operator   string    `json:"operator"`
	Reason     string    `json:"reason"`
	RequestID  string    `json:"request_id"`
	Answer     string    `json:"answer,omitempty"`
	FromStatus string    `json:"from_status,omitempty"`
	ToStatus   string    `json:"to_status"`
	OccurredAt time.Time `json:"occurred_at"`
}

// request 保存每个 (操作者, 请求号) 的首次结果，用于幂等回放。
// 同一操作者的请求号在发行、转让、授权创建/撤销、代转与版税规则设置
// 之间共用。
type request struct {
	Operator  string `json:"operator"`
	RequestID string `json:"request_id"`
	Kind      string `json:"kind"` // "issue" / "issue_batch" / "transfer" / "transfer_batch" / "auth_create" / "auth_revoke" / "proxy_transfer" / "royalty_set" / "intent_create" / "intent_answer" / "intent_withdraw"
	// 规范化后的业务参数签名。签名一致才回放；不一致报请求号冲突。
	Params string `json:"params"`
	// 业务拒绝也落盘：相同参数重提返回首次的拒绝。
	Rejected bool   `json:"rejected"`
	Reason   string `json:"reject_reason"` // 哨兵错误对应的稳定标识
	// 成功结果。
	ItemID  string `json:"item_id,omitempty"`
	AuthID  string `json:"auth_id,omitempty"`
	FromID  string `json:"from_id,omitempty"`
	ToID    string `json:"to_id,omitempty"`
	Version int64  `json:"version,omitempty"`
	TxSeq   int64  `json:"tx_seq,omitempty"`
	// IntentID 与 Status 记录拆分意向类请求的结果（意向编号与操作后的
	// 意向状态）。
	IntentID string `json:"intent_id,omitempty"`
	Status   string `json:"status,omitempty"`
	// SeriesID 与 Shares 记录版税规则设置的结果（本次生效的规则）。
	SeriesID string         `json:"series_id,omitempty"`
	Shares   []royaltyShare `json:"shares,omitempty"`
	// Batch 记录整批发行各件的首次结果（按提交顺序），仅 kind 为
	// issue_batch 时使用；旧登记册中的请求没有该字段。
	Batch []batchItemResult `json:"batch,omitempty"`
	// TransferBatch 记录整批转让各件的首次结果（按提交顺序），仅 kind
	// 为 transfer_batch 时使用；版税金额回放时从 Royalties 按序号补全。
	TransferBatch []batchTransferItemResult `json:"transfer_batch,omitempty"`
}

// batchItemResult 是整批发行中一件藏品落盘的首次发行结果，用于幂等回放。
type batchItemResult struct {
	ItemID  string `json:"item_id"`
	OwnerID string `json:"owner_id"`
	TxSeq   int64  `json:"tx_seq"`
}

// batchTransferItemResult 是整批转让中一件藏品落盘的首次转让结果，用于
// 幂等回放；价款、应付明细与余款按 TxSeq 从版税应付记录补全。
type batchTransferItemResult struct {
	ItemID  string `json:"item_id"`
	FromID  string `json:"from_id"`
	ToID    string `json:"to_id"`
	Version int64  `json:"version"`
	TxSeq   int64  `json:"tx_seq"`
}

func newSnapshot() *snapshot {
	return &snapshot{
		Version:   stateVersion,
		Accounts:  make(map[string]account),
		Series:    make(map[string]series),
		Items:     make(map[string]item),
		Holdings:  make(map[string]holding),
		Requests:  make(map[string]request),
		Authzs:    make(map[string]authzRec),
		Royalties: make(map[int64]royaltyRec),
		Intents:   make(map[string]intentRec),
	}
}

func (s *snapshot) validate() error {
	if s.Version != stateVersion {
		return fmt.Errorf("%w: 不支持的快照版本 %d", ErrCorrupt, s.Version)
	}
	if s.Accounts == nil || s.Series == nil || s.Items == nil ||
		s.Holdings == nil || s.Requests == nil {
		return fmt.Errorf("%w: 快照内容不完整", ErrCorrupt)
	}
	if s.NextSeq < int64(len(s.History)) {
		return fmt.Errorf("%w: 历史序号不连续", ErrCorrupt)
	}
	if s.Authzs == nil {
		// 兼容旧版本写入的快照：授权表按需惰性建立。
		s.Authzs = make(map[string]authzRec)
	}
	if s.NextAuthSeq < int64(len(s.AuthEvents)) {
		return fmt.Errorf("%w: 授权变更序号不连续", ErrCorrupt)
	}
	if s.Royalties == nil {
		// 兼容旧版本写入的快照：版税应付表按需惰性建立；旧转让没有
		// 应付记录，查询时按价款 0 处理，不补造明细。
		s.Royalties = make(map[int64]royaltyRec)
	}
	if s.NextRoyaltySeq < int64(len(s.RoyaltyEvents)) {
		return fmt.Errorf("%w: 版税规则变更序号不连续", ErrCorrupt)
	}
	if s.Intents == nil {
		// 兼容旧版本写入的快照：拆分意向表按需惰性建立。
		s.Intents = make(map[string]intentRec)
	}
	if s.NextIntentSeq < int64(len(s.IntentEvents)) {
		return fmt.Errorf("%w: 拆分意向变更序号不连续", ErrCorrupt)
	}
	s.rekeyRequests()
	return nil
}

// rekeyRequests 按每条请求记录自身保存的完整操作者账户编号与请求号重建
// 请求表的键。旧版本快照的键由账户编号与请求号直接拼接而成，含零字符
// （U+0000）时不同账户的不同请求会得到相同的键；落盘记录本身始终保存
// 真实的提交账户与请求号，据此重建后旧请求仍归原提交账户所有，使用原
// 参数即可回放原结果，碰巧混淆的另一组编号也不会占用或覆盖原请求。
// 该重建对任意字符组合都是幂等的，每次加载都执行。
func (s *snapshot) rekeyRequests() {
	reqs := make(map[string]request, len(s.Requests))
	for _, req := range s.Requests {
		reqs[requestKey(req.Operator, req.RequestID)] = req
	}
	s.Requests = reqs
}

// store 负责一个登记册目录的加锁、读取与原子写入。
type store struct {
	dir  string
	lock *os.File // 跨进程 flock
}

func dataFile(dir string) string { return filepath.Join(dir, "registry.json") }
func lockFile(dir string) string { return filepath.Join(dir, "registry.lock") }
func tempFile(dir string) string { return filepath.Join(dir, ".registry.json.tmp") }

// acquireLock 在登记册目录中以非阻塞方式取独占 flock。
func acquireLock(dir string) (*os.File, error) {
	f, err := os.OpenFile(lockFile(dir), os.O_CREATE|os.O_RDWR, fileMode)
	if err != nil {
		return nil, fmt.Errorf("registry: 无法打开锁文件: %w", err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		f.Close()
		if errors.Is(err, syscall.EWOULDBLOCK) {
			return nil, ErrLocked
		}
		return nil, fmt.Errorf("registry: 无法锁定登记册: %w", err)
	}
	return f, nil
}

// load 读取快照。文件不存在时返回空快照；文件存在但无法读取或解析时
// 返回 ErrCorrupt，绝不静默当成空登记册。
func load(dir string) (*snapshot, error) {
	b, err := os.ReadFile(dataFile(dir))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return newSnapshot(), nil
		}
		return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
	}
	if len(b) == 0 {
		return nil, fmt.Errorf("%w: 数据文件为空", ErrCorrupt)
	}
	var s snapshot
	if err := json.Unmarshal(b, &s); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
	}
	if err := s.validate(); err != nil {
		return nil, err
	}
	return &s, nil
}

// save 以 temp 文件 + fsync + rename + 目录 fsync 的方式原子替换快照。
// 在持有全局锁时调用：写入与状态修改在同一临界区，进程被杀时要么
// 完整保留旧状态，要么完整呈现新状态。
func (st *store) save(s *snapshot) error {
	b, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("registry: 序列化失败: %w", err)
	}
	tmp := tempFile(st.dir)
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, fileMode)
	if err != nil {
		return fmt.Errorf("registry: 无法写入登记册: %w", err)
	}
	ok := false
	defer func() {
		if !ok {
			f.Close()
			os.Remove(tmp)
		}
	}()
	if _, err := f.Write(b); err != nil {
		return fmt.Errorf("registry: 写入失败: %w", err)
	}
	if err := f.Sync(); err != nil {
		return fmt.Errorf("registry: 落盘失败: %w", err)
	}
	if err := f.Close(); err != nil {
		return fmt.Errorf("registry: 关闭临时文件失败: %w", err)
	}
	if err := os.Rename(tmp, dataFile(st.dir)); err != nil {
		return fmt.Errorf("registry: 替换数据文件失败: %w", err)
	}
	if dirFd, err := os.Open(st.dir); err == nil {
		_ = dirFd.Sync()
		dirFd.Close()
	}
	ok = true
	return nil
}

package registry

import (
	"errors"
	"os"
	"testing"
	"time"
)

// 本文件为创建代转授权补充"保存失败"场景的回归保障，与单件/整批发行、
// 单件/整批转让（issue/transfer/batch/batch_transfer_save_failure_test.go）
// 行为对齐：成功或状态类业务拒绝（授权编号占用、账户停用、持有版本不符）
// 都以保存完成为准。本次结果尚未写入原登记册而保存失败时，必须返回实际
// 保存错误——不能报告创建成功，也不能只返回原业务拒绝；结果为空（授权
// 编号与状态为空、绑定版本为零、不标回放、业务错误为空），请求号、授权
// 历史序号都不被这次未保存的操作消耗，即使失败后原数据暂时无法读取、
// 状态未能按磁盘重建，也不留下任何新增授权、创建记录或请求号占用。
// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已满足请求则正常
// 创建，首次重提不标回放。
//
// 失败注入方式与其他场景共用：在临时文件路径 .registry.json.tmp 上预先
// 建一个目录，save 在 OpenFile 阶段即以 EISDIR 失败，原快照完好可读；
// 另有用例同时破坏数据文件，覆盖"原数据暂时无法读取"的情形。

// assertCreateAuthzSaveFailureEmpty 核对"保存失败"的返回：error 是保存
// 错误而非创建成功或任何业务拒绝；结果为空——不携带授权编号、状态或
// 绑定版本，业务错误为空，也不标记为重复返回。
func assertCreateAuthzSaveFailureEmpty(t *testing.T, res CreateAuthorizationResult, err error) {
	t.Helper()
	assertSaveFailureError(t, err)
	if res.AuthID != "" || res.Status != "" || res.GrantVer != 0 ||
		res.Replayed || res.Err != nil {
		t.Fatalf("保存失败必须返回空结果: %+v", res)
	}
}

// assertAuthzRequestFree 核对请求号未被这次未保存的操作占用、授权历史
// 序号未被消耗（在同一个已打开的登记册上检查）。
func assertAuthzRequestFree(t *testing.T, r *Registry, req CreateAuthorizationRequest, wantNextAuthSeq int64) {
	t.Helper()
	if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
		t.Fatalf("未保存的结果不应占用请求号 %s", req.RequestID)
	}
	if r.state.NextAuthSeq != wantNextAuthSeq {
		t.Fatalf("NextAuthSeq = %d, want %d", r.state.NextAuthSeq, wantNextAuthSeq)
	}
}

// assertAuthzAbsent 核对失败的新授权查询为不存在，且藏品的授权历史保持
// 操作前的内容与条数。
func assertAuthzAbsent(t *testing.T, r *Registry, authID, itemID string, wantEvents int) {
	t.Helper()
	if _, err := r.GetAuthorization(authID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("未保存的授权 %s 应查询为不存在: %v", authID, err)
	}
	evs, err := r.AuthorizationHistory(itemID)
	if err != nil {
		t.Fatalf("AuthorizationHistory %s: %v", itemID, err)
	}
	if len(evs) != wantEvents {
		t.Fatalf("授权历史应保持 %d 条: %+v", wantEvents, evs)
	}
}

// TestCreateAuthzSuccessSaveFailure 覆盖：创建授权的成功结果落盘失败时
// 返回保存错误、结果为空；同一个仍打开的登记册中授权查询为不存在、授权
// 历史为空、请求号与授权历史序号都未被消耗、藏品持有不变。保存条件恢复
// 后，其他操作成功保存不会把这次未保存的授权带入登记册；用完全相同的
// 请求重提正常创建（不标回放），此后相同请求回放首次成功。
func TestCreateAuthzSuccessSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	req := createAuthReq(r, "a1", time.Hour)

	blockBatchSave(t, r)
	res, err := r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	assertAuthzRequestFree(t, r, req, 0)
	assertAuthzAbsent(t, r, "a1", "i1", 0)
	assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)

	// 保存条件未恢复时再次提交同一请求：仍重新尝试保存并失败，不能把
	// 上次未保存的结果当成已保存回放。
	res, err = r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	assertAuthzRequestFree(t, r, req, 0)

	// 保存条件恢复后，其他操作成功保存也不能把这次未保存的授权或创建
	// 记录带入登记册。
	restoreBatchSave(t, r)
	if err := r.RegisterAccount("dave", "路人"); err != nil {
		t.Fatal(err)
	}
	assertAuthzRequestFree(t, r, req, 0)
	assertAuthzAbsent(t, r, "a1", "i1", 0)

	// 用完全相同的请求重提：正常创建，不标回放。
	res, err = r.CreateAuthorization(req)
	if err != nil {
		t.Fatalf("恢复后重提应正常创建: %v", err)
	}
	if res.Replayed || res.Err != nil || res.AuthID != "a1" ||
		res.Status != AuthActive || res.GrantVer != 1 {
		t.Fatalf("重提结果异常: %+v", res)
	}
	a, err := r.GetAuthorization("a1")
	if err != nil {
		t.Fatal(err)
	}
	if a.Status != AuthActive || a.GrantVer != 1 || a.GranterID != "alice" {
		t.Fatalf("授权内容异常: %+v", a)
	}
	evs, err := r.AuthorizationHistory("i1")
	if err != nil || len(evs) != 1 || evs[0].Seq != 1 || evs[0].Kind != "create" {
		t.Fatalf("授权历史异常: %+v, %v", evs, err)
	}

	// 成功结果保存后，相同请求回放首次成功。
	res, err = r.CreateAuthorization(req)
	if err != nil || !res.Replayed || res.AuthID != "a1" ||
		res.Status != AuthActive || res.GrantVer != 1 {
		t.Fatalf("成功后重提应回放: %+v, err %v", res, err)
	}
}

// TestCreateAuthzSuccessSaveFailureUnreadableDisk 覆盖：保存失败且原数据
// 暂时无法读取（状态未能按磁盘重建）时，未保存的授权、创建记录与请求号
// 占用也不能留在当前登记册中；恢复正常读写后，其他操作成功保存不带入
// 这次未保存的内容，原请求重提正常创建。
func TestCreateAuthzSuccessSaveFailureUnreadableDisk(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	req := createAuthReq(r, "a1", time.Hour)

	// 让保存失败，同时让原数据暂时无法读取：commit 无法按磁盘重建状态。
	orig, err := os.ReadFile(dataFile(r.dir))
	if err != nil {
		t.Fatal(err)
	}
	blockBatchSave(t, r)
	if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
		t.Fatal(err)
	}

	res, err := r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	// 状态未能重建时也必须显式撤销：同一个仍打开的登记册中查不到这次
	// 未保存的授权与创建记录，请求号与授权历史序号都未被消耗。
	assertAuthzRequestFree(t, r, req, 0)
	assertAuthzAbsent(t, r, "a1", "i1", 0)
	assertHoldingUnchanged(t, r, "i1", "alice", 1, 1)

	// 恢复正常读写。
	if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
		t.Fatal(err)
	}
	restoreBatchSave(t, r)

	// 其他操作成功保存不能把这次未保存的授权或请求号占用带入登记册。
	if err := r.RegisterAccount("dave", "路人"); err != nil {
		t.Fatal(err)
	}
	assertAuthzRequestFree(t, r, req, 0)
	assertAuthzAbsent(t, r, "a1", "i1", 0)

	// 用完全相同的请求重提：正常创建，不标回放。
	res, err = r.CreateAuthorization(req)
	if err != nil {
		t.Fatalf("恢复后重提应正常创建: %v", err)
	}
	if res.Replayed || res.AuthID != "a1" || res.Status != AuthActive || res.GrantVer != 1 {
		t.Fatalf("重提结果异常: %+v", res)
	}
	if r.state.NextAuthSeq != 1 {
		t.Fatalf("授权历史序号应连续: NextAuthSeq = %d", r.state.NextAuthSeq)
	}
}

// TestCreateAuthzRejectSaveFailureRetrySameState 覆盖：持有版本不符的拒绝
// 落盘失败时返回保存错误、结果为空、请求号不被占用；保存恢复且拒绝条件
// 仍在时，用完全相同的请求重提会重新保存此次拒绝，保存成功后才返回业务
// 错误（首次重提不标回放）；此后相同请求回放该拒绝。
func TestCreateAuthzRejectSaveFailureRetrySameState(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	// i1 当前为 alice 版本 1，期望版本 2：ErrConflict。
	req := createAuthReq(r, "a1", time.Hour)
	req.ExpectedVer = 2

	blockBatchSave(t, r)
	res, err := r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	assertAuthzRequestFree(t, r, req, 0)
	assertAuthzAbsent(t, r, "a1", "i1", 0)

	// 保存条件未恢复时再次提交同一请求：仍按当时状态重新判断并再次尝试
	// 保存，不能把上次未保存的拒绝当成已保存的拒绝回放。
	res, err = r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	assertAuthzRequestFree(t, r, req, 0)

	// 保存条件恢复、拒绝条件仍在：重提重新保存此次拒绝，保存成功后返回
	// 业务错误本身并附授权编号，这次重新处理不标记为重复。
	restoreBatchSave(t, r)
	res, err = r.CreateAuthorization(req)
	if !errors.Is(err, ErrConflict) {
		t.Fatalf("重提应在保存成功后返回业务拒绝 ErrConflict: %v", err)
	}
	if res.Replayed || res.AuthID != "a1" || !errors.Is(res.Err, ErrConflict) ||
		res.Status != "" || res.GrantVer != 0 {
		t.Fatalf("重提结果异常: %+v", res)
	}
	if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; !ok {
		t.Fatal("拒绝保存成功后应登记请求结果")
	}
	// 拒绝不创建授权，也不消耗授权历史序号。
	assertAuthzAbsent(t, r, "a1", "i1", 0)
	if r.state.NextAuthSeq != 0 {
		t.Fatalf("拒绝不应消耗授权历史序号: NextAuthSeq = %d", r.state.NextAuthSeq)
	}

	// 拒绝已保存：相同内容重提回放原拒绝。
	res, err = r.CreateAuthorization(req)
	if !errors.Is(err, ErrConflict) || !res.Replayed || res.AuthID != "a1" ||
		!errors.Is(res.Err, ErrConflict) {
		t.Fatalf("保存后的重提应回放原拒绝: %+v, err %v", res, err)
	}
}

// TestCreateAuthzRejectSaveFailureRetryAfterStateChange 覆盖：未保存的冲突
// 拒绝不阻碍后续重提——保存条件恢复后，藏品经合法转让恰好达到原请求要求
// 的持有人与版本，且授权仍未到期，用完全相同的请求重提应正常创建。
func TestCreateAuthzRejectSaveFailureRetryAfterStateChange(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupWorld(t, r)
	if err := r.RegisterAccount("carol", "接收人"); err != nil {
		t.Fatal(err)
	}
	// i1 发行给 bob（版本 1）。
	if _, err := r.Issue(issueReq("i1", "bob")); err != nil {
		t.Fatal(err)
	}
	// alice 期望自己持有版本 2：当前为 bob 版本 1，先被冲突拒绝。
	req := CreateAuthorizationRequest{
		Operator: "alice", Reason: "委托代转", RequestID: "create-a1",
		AuthID: "a1", ItemID: "i1", TrusteeID: "bob", ToID: "carol",
		ExpectedOwner: "alice", ExpectedVer: 2,
		ExpiresAt: r.now().Add(time.Hour),
	}

	blockBatchSave(t, r)
	res, err := r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	assertAuthzRequestFree(t, r, req, 0)

	// 保存条件恢复后，bob 把 i1 合法转让给 alice：i1 变为 alice 版本 2，
	// 恰好满足原请求的期望持有人与版本。
	restoreBatchSave(t, r)
	if _, err := r.Transfer(xferReq("bob", "i1", "alice", 1, "rt-i1")); err != nil {
		t.Fatal(err)
	}

	// 用完全相同的原请求重提：按当前业务状态判断，正常创建不标回放。
	res, err = r.CreateAuthorization(req)
	if err != nil {
		t.Fatalf("状态满足后重提应正常创建，不能回放未保存的冲突: %v", err)
	}
	if res.Replayed || res.Err != nil || res.AuthID != "a1" ||
		res.Status != AuthActive || res.GrantVer != 2 {
		t.Fatalf("重提结果异常: %+v", res)
	}
	a, err := r.GetAuthorization("a1")
	if err != nil {
		t.Fatal(err)
	}
	if a.Status != AuthActive || a.GrantVer != 2 || a.GranterID != "alice" {
		t.Fatalf("授权内容异常: %+v", a)
	}

	// 成功结果保存后，相同请求回放首次成功。
	replay, err := r.CreateAuthorization(req)
	if err != nil || !replay.Replayed || replay.GrantVer != 2 {
		t.Fatalf("成功后重提应回放: %+v, err %v", replay, err)
	}
}

// TestCreateAuthzRejectSaveFailureAuthIDTaken 覆盖：授权编号已被占用的
// 拒绝落盘失败时返回保存错误、结果为空；失败请求使用了已存在的授权
// 编号，原授权及其历史完整保留；保存恢复后重提返回 ErrAlreadyExists。
func TestCreateAuthzRejectSaveFailureAuthIDTaken(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
		t.Fatal(err)
	}
	// 换一个请求号再次使用已占用的授权编号 a1：ErrAlreadyExists。
	req := createAuthReq(r, "a1", time.Hour)
	req.RequestID = "create-a1-again"

	blockBatchSave(t, r)
	res, err := r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	assertAuthzRequestFree(t, r, req, 1)

	// 原授权及其创建历史完整保留。
	a, err := r.GetAuthorization("a1")
	if err != nil {
		t.Fatalf("原授权不应受失败请求影响: %v", err)
	}
	if a.Status != AuthActive || a.GranterID != "alice" || a.TrusteeID != "bob" ||
		a.ToID != "carol" || a.GrantVer != 1 {
		t.Fatalf("原授权内容被改变: %+v", a)
	}
	evs, err := r.AuthorizationHistory("i1")
	if err != nil || len(evs) != 1 || evs[0].Kind != "create" || evs[0].AuthID != "a1" {
		t.Fatalf("原授权历史被改变: %+v, %v", evs, err)
	}

	restoreBatchSave(t, r)
	res, err = r.CreateAuthorization(req)
	if !errors.Is(err, ErrAlreadyExists) {
		t.Fatalf("重提应在保存成功后返回 ErrAlreadyExists: %v", err)
	}
	if res.Replayed || res.AuthID != "a1" || !errors.Is(res.Err, ErrAlreadyExists) {
		t.Fatalf("编号占用拒绝的重提结果异常: %+v", res)
	}
	// 原授权内容仍保持不变。
	a, _ = r.GetAuthorization("a1")
	if a.Status != AuthActive || a.GrantVer != 1 {
		t.Fatalf("原授权内容被改变: %+v", a)
	}
}

// TestCreateAuthzRejectSaveFailureAccountInactive 覆盖：账户停用的拒绝
// 落盘失败时同样返回保存错误、结果为空；保存恢复后重提重新保存拒绝并
// 返回账户错误。
func TestCreateAuthzRejectSaveFailureAccountInactive(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)
	if err := r.DeactivateAccount("bob"); err != nil {
		t.Fatal(err)
	}
	req := createAuthReq(r, "a1", time.Hour)

	blockBatchSave(t, r)
	res, err := r.CreateAuthorization(req)
	assertCreateAuthzSaveFailureEmpty(t, res, err)
	assertAuthzRequestFree(t, r, req, 0)
	assertAuthzAbsent(t, r, "a1", "i1", 0)

	restoreBatchSave(t, r)
	res, err = r.CreateAuthorization(req)
	if !errors.Is(err, ErrAccountInactive) {
		t.Fatalf("重提应在保存成功后返回 ErrAccountInactive: %v", err)
	}
	if res.AuthID != "a1" || !errors.Is(res.Err, ErrAccountInactive) || res.Replayed {
		t.Fatalf("账户停用拒绝的重提结果异常: %+v", res)
	}
}

// TestCreateAuthzValidationErrorIgnoresSaveFailure 覆盖：必填内容缺失、
// 到期时间不合法与引用对象不存在的请求不占用请求号、不要求保存，即使
// 数据位置暂时不可写也仍返回原参数/引用错误，不能改报保存错误。
func TestCreateAuthzValidationErrorIgnoresSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	authzWorld(t, r)

	blockBatchSave(t, r)
	defer restoreBatchSave(t, r)

	// 引用不存在的藏品：返回 ErrNotFound，不是保存错误。
	notFoundReq := createAuthReq(r, "a-nf", time.Hour)
	notFoundReq.ItemID = "nope"
	res, err := r.CreateAuthorization(notFoundReq)
	if !errors.Is(err, ErrNotFound) {
		t.Fatalf("引用不存在应返回 ErrNotFound，不能改报保存错误: %v", err)
	}
	if res.AuthID != "a-nf" || !errors.Is(res.Err, ErrNotFound) {
		t.Fatalf("引用不存在的结果异常: %+v", res)
	}
	assertAuthzRequestFree(t, r, notFoundReq, 0)

	// 到期时间不晚于当前时间：返回 ErrInvalidArgument，不是保存错误。
	expiredReq := createAuthReq(r, "a-exp", -time.Hour)
	res, err = r.CreateAuthorization(expiredReq)
	if !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("到期时间不合法应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
	}
	if res.AuthID != "a-exp" || !errors.Is(res.Err, ErrInvalidArgument) {
		t.Fatalf("到期时间不合法的结果异常: %+v", res)
	}
	assertAuthzRequestFree(t, r, expiredReq, 0)

	// 必填内容缺失：返回 ErrInvalidArgument，不是保存错误。
	missingReq := createAuthReq(r, "a-miss", time.Hour)
	missingReq.TrusteeID = ""
	if _, err := r.CreateAuthorization(missingReq); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("必填缺失应返回 ErrInvalidArgument，不能改报保存错误: %v", err)
	}
	assertAuthzRequestFree(t, r, missingReq, 0)
}

package registry

import "time"

// Account 是账户登记信息。停用后仍可查询其原有藏品与历史。
type Account struct {
	ID       string // 唯一编号
	Metadata string // 文字元数据，可为空
	Active   bool   // 是否可用；停用后不能发行、发起或接收新的转让
}

// Series 是系列信息。仅创建账户可以发行藏品或封存系列。
type Series struct {
	ID        string // 系列编号
	CreatorID string // 创建账户编号
	Metadata  string // 文字元数据
	Sealed    bool   // 是否已封存；封存不可撤销
}

// Item 是单件藏品的静态登记信息。
type Item struct {
	ID         string // 唯一藏品编号，同一编号不能产生第二件藏品
	SeriesID   string // 所属系列
	BatchNo    string // 批次号
	Metadata   string // 文字元数据
	IssuedTxID int64  // 发行记录在历史中的序号
}

// Holding 是一件藏品的当前持有状态。
type Holding struct {
	ItemID  string // 藏品编号
	OwnerID string // 当前持有人
	Version int64  // 当前持有版本：发行后为 1，每次成功转让加 1
}

// HistoryEntry 是一条发行或成功转让记录，按发生先后排列。
type HistoryEntry struct {
	Seq       int64  // 严格递增的记录序号，也即发生顺序
	Kind      string // "issue" 或 "transfer"（代转仍为 transfer）
	ItemID    string // 藏品编号
	Operator  string // 操作者账户编号
	Reason    string // 操作原因
	RequestID string // 请求号
	// FromID 是转让前持有人；发行前为空。
	FromID string
	// ToID 是转让后持有人（发行时为初始持有人）。
	ToID string
	// FromVersion 是转让前持有版本；发行前为 0（语义上为空）。
	FromVersion int64
	// ToVersion 是转让后持有版本（发行后为 1）。
	ToVersion int64
	// AuthID 是代转所使用的授权编号；直接转让与发行时为空。
	AuthID string
}

// IssueRequest 是发行请求的业务参数（幂等判定以此为准）。
type IssueRequest struct {
	Operator  string // 操作者，必须是系列创建账户且可用
	Reason    string // 原因
	RequestID string // 请求号，同一操作者在发行与转让之间共用
	ItemID    string // 唯一藏品编号
	SeriesID  string // 所属系列
	BatchNo   string // 批次号
	Metadata  string // 藏品文字元数据
	HolderID  string // 初始持有人，必须是已登记且可用的账户
}

// IssueBatchEntry 是整批发行中一件藏品的提交内容。
type IssueBatchEntry struct {
	ItemID   string // 唯一藏品编号，清单内不能重复
	Metadata string // 藏品文字元数据，可为空
	HolderID string // 初始持有人，必须是已登记且可用的账户
}

// IssueBatchRequest 是整批发行请求的业务参数（幂等判定以此为准，含条目
// 顺序）。整批共用操作者、原因、请求号、系列与批次号。
type IssueBatchRequest struct {
	Operator  string            // 操作者，必须是系列创建账户且可用
	Reason    string            // 原因
	RequestID string            // 请求号，与单件发行、转让等共用同一操作者的请求号范围
	SeriesID  string            // 所属系列，整批同一系列
	BatchNo   string            // 批次号，整批同一批次；不同请求可沿用同一批次号
	Entries   []IssueBatchEntry // 发行清单，按提交顺序依次发行；不能为空
}

// IssueBatchItem 是整批发行中一件藏品的发行结果。
type IssueBatchItem struct {
	ItemID  string // 藏品编号
	OwnerID string // 初始持有人
	Version int64  // 持有版本，恒为 1
	TxSeq   int64  // 发行历史序号；整批内连续递增
}

// IssueBatchResult 是整批发行请求的处理结果。
type IssueBatchResult struct {
	Items []IssueBatchItem // 各件的发行结果，按提交顺序排列；拒绝时为空
	// ItemID 是业务拒绝所涉及的藏品编号（如编号已占用、初始持有人不可用的
	// 那一件）；拒绝与具体某件无关时为空。
	ItemID   string
	Replayed bool  // 是否为重复提交回放的首次结果
	Err      error // 首次或本次的业务拒绝；成功时为 nil
}

// TransferRequest 是转让请求的业务参数。
type TransferRequest struct {
	Operator      string // 操作者，必须是当前持有人且可用
	Reason        string // 原因
	RequestID     string // 请求号
	ItemID        string // 藏品编号
	ExpectedOwner string // 期望当前持有人（通常即发起人）
	ExpectedVer   int64  // 期望当前持有版本
	ToID          string // 接收人，必须已登记、可用且不同于当前持有人
	// Price 是成交价款，以分计，非负；未填按 0。负数按参数错误拒绝。
	Price int64
}

// IssueResult 是发行请求的处理结果。
type IssueResult struct {
	ItemID   string // 藏品编号
	OwnerID  string // 初始持有人
	Version  int64  // 持有版本，恒为 1
	TxSeq    int64  // 发行历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 首次或本次的业务拒绝；成功时为 nil
}

// TransferResult 是转让请求的处理结果。
type TransferResult struct {
	ItemID   string // 藏品编号
	FromID   string // 转让前持有人
	ToID     string // 转让后持有人
	Version  int64  // 转让后版本
	TxSeq    int64  // 转让历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 业务拒绝；成功时为 nil
	// Price 是本笔成交价款（分）；Payables 是各版税收款账户的应付明细
	// （含零金额）；Remainder 是扣除应付后归转让前持有人的剩余收入。
	Price     int64
	Payables  []RoyaltyPayable
	Remainder int64
}

// TransferBatchEntry 是整批转让中一件藏品的提交内容。
type TransferBatchEntry struct {
	ItemID        string // 藏品编号，清单内不能重复
	ToID          string // 接收账户，必须已登记且可用；不同条目可重复
	ExpectedOwner string // 期望当前持有人；操作者必须是每件的当前持有人
	ExpectedVer   int64  // 期望当前持有版本，必须为正
	// Price 是本件成交价款，以分计，非负；未填按 0。负数按参数错误拒绝。
	Price int64
}

// TransferBatchRequest 是整批转让请求的业务参数（幂等判定以此为准，含
// 条目顺序）。整批共用操作者、原因与请求号；藏品可来自不同系列与发行
// 批次。
type TransferBatchRequest struct {
	Operator  string               // 操作者，必须是每件的当前持有人且可用
	Reason    string               // 原因
	RequestID string               // 请求号，与发行、单件转让、代转等共用同一操作者的请求号范围
	Entries   []TransferBatchEntry // 转让清单，按提交顺序处理与返回；不能为空
}

// TransferBatchItem 是整批转让中一件藏品的转让结果。
type TransferBatchItem struct {
	ItemID   string           // 藏品编号
	FromID   string           // 转让前持有人
	ToID     string           // 转让后持有人
	Version  int64            // 转让后版本（各件分别加一）
	TxSeq    int64            // 转让历史序号；整批内连续递增
	Price    int64            // 本件成交价款（分）
	Payables []RoyaltyPayable // 本件各版税收款账户的应付明细（含零金额）
	// Remainder 是本件扣除应付后归转让前持有人的剩余收入。
	Remainder int64
}

// TransferBatchResult 是整批转让请求的处理结果。
type TransferBatchResult struct {
	Items []TransferBatchItem // 各件的转让结果，按提交顺序排列；拒绝时为空
	// ItemID 是业务拒绝所涉及的藏品编号（清单顺序最前的失败藏品）；
	// 操作者层面的拒绝（未登记或停用）时为空。
	ItemID   string
	Replayed bool  // 是否为重复提交回放的首次结果
	Err      error // 首次或本次的业务拒绝；成功时为 nil
}

// 授权生命周期状态。
const (
	// AuthActive 表示授权已创建，尚未撤销、过期或使用。
	AuthActive = "active"
	// AuthRevoked 表示授权已被授权人撤销。
	AuthRevoked = "revoked"
	// AuthExpired 表示授权已过到期时间且尚未使用。
	AuthExpired = "expired"
	// AuthUsed 表示授权已用于一次成功代转。
	AuthUsed = "used"
)

// CreateAuthorizationRequest 是创建限时一次性代转授权的业务参数
// （幂等判定以此为准）。
type CreateAuthorizationRequest struct {
	Operator      string    // 操作者，必须是当前持有人（授权人）且可用
	Reason        string    // 原因
	RequestID     string    // 请求号，与发行、转让共用同一操作者的请求号范围
	AuthID        string    // 唯一授权编号
	ItemID        string    // 已发行藏品编号
	TrusteeID     string    // 受托账户，可凭授权发起代转
	ToID          string    // 固定接收账户，代转只能转入该账户
	ExpectedOwner string    // 期望当前持有人
	ExpectedVer   int64     // 期望当前持有版本；授权绑定该持有版本
	ExpiresAt     time.Time // 绝对到期时间，必须晚于当前时间
	// Price 是代转成交价款（分），在创建授权时确定，执行代转时不得改价；
	// 非负，未填按 0。
	Price int64
}

// RevokeAuthorizationRequest 是撤销授权的业务参数。
type RevokeAuthorizationRequest struct {
	Operator  string // 操作者，必须是授权人
	Reason    string // 原因
	RequestID string // 请求号
	AuthID    string // 待撤销的授权编号
}

// ProxyTransferRequest 是受托人凭授权发起代转的业务参数。
type ProxyTransferRequest struct {
	Operator  string // 操作者，必须是授权的受托人
	Reason    string // 原因
	RequestID string // 请求号
	AuthID    string // 使用的授权编号
}

// Authorization 是一份代转授权的当前内容与状态。
type Authorization struct {
	ID        string    // 授权编号
	ItemID    string    // 绑定的藏品
	GranterID string    // 授权人（创建时的持有人）
	TrusteeID string    // 受托账户
	ToID      string    // 固定接收账户
	ExpiresAt time.Time // 绝对到期时间
	GrantVer  int64     // 创建时绑定的持有版本
	// Price 是创建时确定的代转成交价款（分）；旧登记册中的授权按 0。
	Price     int64
	Status    string    // 当前状态：AuthActive/AuthRevoked/AuthExpired/AuthUsed
	UsedTxSeq int64     // 成功代转的历史序号；未使用为 0
	UsedAt    time.Time // 成功代转时间；未使用为零值
	CreatedAt time.Time // 创建时间
	RevokedAt time.Time // 撤销时间；未撤销为零值
}

// AuthorizationEvent 是授权变更记录中的一条。
type AuthorizationEvent struct {
	Seq        int64     // 授权变更记录内严格递增的序号
	AuthID     string    // 授权编号
	ItemID     string    // 藏品编号
	Kind       string    // "create" / "revoke" / "use"
	Operator   string    // 操作者账户编号（use 时为受托人）
	Reason     string    // 操作原因
	RequestID  string    // 请求号
	FromStatus string    // 变更前状态（create 前为空）
	ToStatus   string    // 变更后状态
	TxSeq      int64     // use 时关联的藏品转让历史序号，否则为 0
	OccurredAt time.Time // 发生时间
}

// CreateAuthorizationResult 是创建授权的结果。
type CreateAuthorizationResult struct {
	AuthID   string
	Status   string
	GrantVer int64
	Replayed bool
	Err      error
}

// RevokeAuthorizationResult 是撤销授权的结果。Replayed 为 true 表示该
// (操作者, 请求号) 曾成功或处于状态类业务拒绝；已撤销后再次撤销也回放
// 首次结果。
type RevokeAuthorizationResult struct {
	AuthID   string
	Status   string
	Replayed bool
	Err      error
}

// ProxyTransferResult 是代转的结果，字段语义与 TransferResult 一致。
type ProxyTransferResult struct {
	AuthID   string // 使用的授权编号
	ItemID   string // 藏品编号
	FromID   string // 转让前持有人
	ToID     string // 转让后持有人
	Version  int64  // 转让后版本
	TxSeq    int64  // 转让历史序号
	Replayed bool   // 是否为重复提交回放的首次结果
	Err      error  // 业务拒绝；成功时为 nil
	// Price 是授权创建时确定的成交价款（分）；Payables 是各版税收款账户
	// 的应付明细（含零金额）；Remainder 是归转让前持有人的剩余收入。
	Price     int64
	Payables  []RoyaltyPayable
	Remainder int64
}

// ---- 版税规则与应付记录 ----

// RoyaltyRateBase 是版税比例的分母：比例以万分之一为单位。
const RoyaltyRateBase = 10000

// RoyaltyShare 是版税规则中一个收款账户的份额。
type RoyaltyShare struct {
	AccountID string // 收款账户，规则内只能出现一次
	Rate      int64  // 比例，万分之一，取值 1..10000；全部份额合计不超过 10000
}

// SetRoyaltyRequest 是设置或清空系列版税规则的业务参数（幂等判定以此
// 为准）。Shares 为空表示清空规则，即不收版税。
type SetRoyaltyRequest struct {
	Operator  string         // 操作者，必须是系列创建账户且可用
	Reason    string         // 原因
	RequestID string         // 请求号，与发行、转让等共用同一操作者的请求号范围
	SeriesID  string         // 系列编号
	Shares    []RoyaltyShare // 新规则；空表示不收版税
}

// SetRoyaltyResult 是设置版税规则的结果。
type SetRoyaltyResult struct {
	SeriesID string         // 系列编号
	Shares   []RoyaltyShare // 本次生效的规则（按收款账户排序规范化后）
	Replayed bool           // 是否为重复提交回放的首次结果
	Err      error          // 业务拒绝；成功时为 nil
}

// RoyaltyEvent 是一次版税规则变更记录，包含操作者、原因、请求号与前后
// 内容；按发生先后排列。
type RoyaltyEvent struct {
	Seq        int64          // 规则变更记录内严格递增的序号
	SeriesID   string         // 系列编号
	Operator   string         // 操作者账户编号
	Reason     string         // 操作原因
	RequestID  string         // 请求号
	Before     []RoyaltyShare // 变更前规则（首次设置前为空）
	After      []RoyaltyShare // 变更后规则
	OccurredAt time.Time      // 发生时间
}

// RoyaltyPayable 是一笔转让中某个版税收款账户的应付明细。
type RoyaltyPayable struct {
	AccountID string // 收款账户
	Rate      int64  // 计算所用比例（万分之一）
	Amount    int64  // 应付金额（分）：价款乘比例除以 10000 向下取整，零金额也保留
}

// TransferRoyalty 是一笔成功转让的版税计算依据与全部金额。
type TransferRoyalty struct {
	TxSeq     int64            // 转让历史序号
	ItemID    string           // 藏品编号
	Price     int64            // 成交价款（分）
	Payables  []RoyaltyPayable // 各收款账户应付明细（含零金额；无规则时为空）
	Remainder int64            // 扣除应付后的剩余收入，归转让前持有人
	OwnerID   string           // 转让前持有人，即剩余收入的归属账户
}

// PayableEntry 是按收款账户查询时的一条应付明细。
type PayableEntry struct {
	TxSeq  int64  // 转让历史序号
	ItemID string // 藏品编号
	Price  int64  // 该笔成交价款（分）
	Rate   int64  // 计算所用比例（万分之一）
	Amount int64  // 应付金额（分）
}

// ---- 藏品拆分意向 ----

// 拆分意向生命周期状态。已失效与已过期不单独落盘，按当前状态与时间实时
// 判断；已拒绝与已撤回是落盘的终态。
const (
	// SplitPending 表示意向已创建，尚有参与账户未答复。
	SplitPending = "pending"
	// SplitAgreed 表示全部参与账户已同意各自份额。
	SplitAgreed = "agreed"
	// SplitRejected 表示任一参与账户拒绝了自己的份额。
	SplitRejected = "rejected"
	// SplitWithdrawn 表示发起人已撤回意向。
	SplitWithdrawn = "withdrawn"
	// SplitInvalid 表示意向已失效：藏品持有版本已变化，或发起人、任一
	// 参与账户已停用；藏品转回原持有人也不能恢复。
	SplitInvalid = "invalid"
	// SplitExpired 表示意向未失效但已过绝对到期时间。
	SplitExpired = "expired"
)

// 参与账户的答复。
const (
	// SplitAnswerAgree 表示同意自己的份额。
	SplitAnswerAgree = "agree"
	// SplitAnswerReject 表示拒绝自己的份额。
	SplitAnswerReject = "reject"
)

// SplitShare 是拆分意向中一个参与账户的份额。份额以万分之一为单位，
// 每份 1..10000，全部份额合计必须为 10000。
type SplitShare struct {
	AccountID string // 参与账户，方案内不能重复
	Share     int64  // 份额，万分之一，取值 1..10000
}

// CreateSplitIntentRequest 是创建拆分意向的业务参数（幂等判定以此为准；
// 份额名单仅排列不同视为相同内容）。
type CreateSplitIntentRequest struct {
	Operator      string       // 操作者，必须是当前持有人（发起人）且可用
	Reason        string       // 原因
	RequestID     string       // 请求号，与发行、转让等共用同一操作者的请求号范围
	IntentID      string       // 唯一意向编号
	ItemID        string       // 已发行藏品编号
	ExpectedOwner string       // 期望当前持有人
	ExpectedVer   int64        // 期望当前持有版本；意向绑定该持有版本
	ExpiresAt     time.Time    // 绝对到期时间，必须晚于当前时间
	Shares        []SplitShare // 分配方案，至少两个账户；发起人可列入，其份额视为已同意
}

// AnswerSplitIntentRequest 是参与账户答复自己份额的业务参数。
type AnswerSplitIntentRequest struct {
	Operator  string // 操作者，必须是方案中的参与账户
	Reason    string // 原因
	RequestID string // 请求号
	IntentID  string // 意向编号
	Agree     bool   // true 同意，false 拒绝
}

// WithdrawSplitIntentRequest 是发起人撤回拆分意向的业务参数。
type WithdrawSplitIntentRequest struct {
	Operator  string // 操作者，必须是发起人
	Reason    string // 原因
	RequestID string // 请求号
	IntentID  string // 意向编号
}

// SplitParty 是拆分意向中一个参与账户的份额与当前答复。
type SplitParty struct {
	AccountID string // 参与账户
	Share     int64  // 份额，万分之一
	// Answer 是该账户的当前答复：SplitAnswerAgree/SplitAnswerReject；
	// 空表示尚未答复。发起人列入方案时创建即为 SplitAnswerAgree。
	Answer string
}

// SplitIntent 是一份拆分意向的当前内容与状态。意向只记录未来拆分的
// 约定，不改变藏品编号、持有人、持有版本与版税应付。
type SplitIntent struct {
	ID          string       // 意向编号
	ItemID      string       // 藏品编号
	InitiatorID string       // 发起人（创建时的持有人）
	Shares      []SplitParty // 分配方案与各方答复（按账户排序）
	GrantVer    int64        // 创建时绑定的持有版本
	ExpiresAt   time.Time    // 绝对到期时间
	Status      string       // 当前状态：SplitPending/SplitAgreed/SplitRejected/SplitWithdrawn/SplitInvalid/SplitExpired
	CreatedAt   time.Time    // 创建时间
	EndedAt     time.Time    // 拒绝或撤回时间；未终结为零值
}

// SplitIntentEvent 是拆分意向变更记录中的一条：创建、首次答复与撤回
// 各记录一条，按发生先后排列。重复答复与重复撤回不新增记录。
type SplitIntentEvent struct {
	Seq        int64     // 意向变更记录内严格递增的序号
	IntentID   string    // 意向编号
	ItemID     string    // 藏品编号
	Kind       string    // "create" / "answer" / "withdraw"
	Operator   string    // 操作者账户编号
	Reason     string    // 操作原因
	RequestID  string    // 请求号
	Answer     string    // answer 时的答复（agree/reject），否则为空
	FromStatus string    // 变更前状态（create 前为空）
	ToStatus   string    // 变更后状态
	OccurredAt time.Time // 发生时间
}

// CreateSplitIntentResult 是创建拆分意向的结果。
type CreateSplitIntentResult struct {
	IntentID string
	Status   string
	GrantVer int64
	Replayed bool
	Err      error
}

// AnswerSplitIntentResult 是答复拆分意向的结果。Status 是答复生效后的
// 意向状态。
type AnswerSplitIntentResult struct {
	IntentID string
	Status   string
	Replayed bool
	Err      error
}

// WithdrawSplitIntentResult 是撤回拆分意向的结果。
type WithdrawSplitIntentResult struct {
	IntentID string
	Status   string
	Replayed bool
	Err      error
}

