443	func TestProxyTransferIdempotentAfterStateChanges(t *testing.T) {
444		r := mustCreate(t, tempDir(t))
445		authzWorld(t, r)
446		if _, err := r.CreateAuthorization(createAuthReq(r, "a1", time.Hour)); err != nil {
447			t.Fatal(err)
448		}
449		req := proxyReq("bob", "a1", "p1")
450		first, err := r.ProxyTransfer(req)
451		if err != nil {
452			t.Fatal(err)
453		}
454		// 成功后代转：藏品再次易手、授权已使用、账户停用、时间越过到期点
455		if _, err := r.Transfer(xferReq("carol", "i1", "bob", 2, "t2")); err != nil {
456			t.Fatal(err)
457		}
458		if err := r.DeactivateAccount("alice"); err != nil {
459			t.Fatal(err)
