461		r.now = func() time.Time { return time.Unix(3_000_000_000, 0) }
462		again, err := r.ProxyTransfer(req)
463		if err != nil {
464			t.Fatalf("successful proxy must replay despite later state changes: %v", err)
465		}
466		if !again.Replayed || again.TxSeq != first.TxSeq || again.Version != 2 ||
467			again.ToID != "carol" || again.FromID != "alice" {
468			t.Fatalf("replayed proxy != first: %+v vs %+v", again, first)
469		}
470		hist, _ := r.History("i1")
471		if len(hist) != 3 { // issue + proxy + later direct transfer
472			t.Fatalf("replay adds no history: %d", len(hist))
473		}
474		h, _ := r.GetHolding("i1")
475		if h.OwnerID != "bob" || h.Version != 3 {
476			t.Fatalf("replay must not change holding: %+v", h)
477		}
478	}
